from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Find the k-th positive integer divisible by at least one denomination."""
    upper = min(coins) * k
    terms = []

    def build(index: int, current_lcm: int, size: int) -> None:
        for i in range(index, len(coins)):
            coin = coins[i]
            next_lcm = current_lcm // gcd(current_lcm, coin) * coin
            if next_lcm > upper:
                continue
            next_size = size + 1
            terms.append((next_lcm, 1 if next_size % 2 else -1))
            build(i + 1, next_lcm, next_size)

    build(0, 1, 0)

    def count_at_most(value: int) -> int:
        return sum(sign * (value // multiple) for multiple, sign in terms)

    lo, hi = 1, upper
    while lo < hi:
        mid = (lo + hi) // 2
        if count_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

