"""Reference implementations for the six assigned Python utility functions."""
from math import gcd
from typing import List


def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending in s with bounded digits."""
    if start > finish or not s or any(int(ch) > limit for ch in s):
        return 0
    suffix_len = len(s)

    def prefix_count(p: int) -> int:
        return 1 if p == 0 else limit * (limit + 1) ** (p - 1)

    def strictly_less(prefix: str) -> int:
        total = 0
        p = len(prefix)
        for i, ch in enumerate(prefix):
            d = ord(ch) - 48
            lo = 1 if i == 0 else 0
            hi = min(limit, d - 1)
            if hi >= lo:
                total += (hi - lo + 1) * (limit + 1) ** (p - i - 1)
            if d < lo or d > limit:
                return total
        return total

    def count_leq(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = str(bound)
        total = sum(prefix_count(length - suffix_len)
                    for length in range(max(1, suffix_len), len(digits)))
        if len(digits) >= suffix_len:
            p = len(digits) - suffix_len
            pref = digits[:p]
            total += strictly_less(pref)
            if s <= digits[p:] and (p == 0 or (pref[0] != "0" and
                    all(ord(ch) - 48 <= limit for ch in pref))):
                total += 1
        return total

    return count_leq(finish) - count_leq(start - 1)


def count_valid_colorings(n: int, m: int) -> int:
    """Count proper colorings of an n-vertex cycle modulo 998244353."""
    mod = 998244353
    return (pow(m - 1, n, mod) +
            (m - 1 if n % 2 == 0 else -(m - 1))) % mod


def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Return twice the black area in [A,C] x [B,D] for the wallpaper pattern."""
    # The coloring is periodic with periods 4 in x and 2 in y. Prefix areas
    # in one period are stored doubled, so all calculations use integers.
    vertical = (0, 3, 6, 7, 8)  # x in [0,r], y in [0,2]
    horizontal = (0, 4)         # x in [0,4], y in [0,s]
    partial = (0, 2, 3, 3, 4)  # x in [0,r], y in [0,1]

    def prefix(x: int, y: int) -> int:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        return (8 * qx * qy + horizontal[ry] * qx
                + vertical[rx] * qy + (partial[rx] if ry else 0))

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th positive integer divisible by at least one denomination."""
    useful = sorted(set(coins))
    filtered = []
    for c in useful:
        if not any(c % d == 0 for d in filtered):
            filtered.append(c)

    high = min(filtered) * k
    cap = high + 1
    lcms = [1]
    signs = [-1]  # The empty subset has the opposite sign to a singleton.
    for c in filtered:
        old_len = len(lcms)
        for i in range(old_len):
            new_lcm = lcms[i] // gcd(lcms[i], c) * c
            lcms.append(min(new_lcm, cap))
            signs.append(-signs[i])

    def count(x: int) -> int:
        return sum(sign * (x // lcm)
                   for lcm, sign in zip(lcms[1:], signs[1:]) if lcm <= x)

    low = 1
    while low < high:
        mid = (low + high) // 2
        if count(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize |k - OR(subarray)| over all non-empty contiguous subarrays."""
    best = float("inf")
    endings = set()
    for value in nums:
        current = {value}
        current.update(previous | value for previous in endings)
        for combined in current:
            difference = abs(combined - k)
            if difference < best:
                best = difference
                if best == 0:
                    return 0
        endings = current
    return int(best)


