    """Count integers with equally many even/odd digits, divisible by k."""
    def count_at_most(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = [int(ch) for ch in str(bound)]
        # state: (even-minus-odd balance, remainder, started, tight)
        dp = {(0, 0, False, True): 1}
        for limit_digit in digits:
            nxt = {}
            for (balance, remainder, started, tight), ways in dp.items():
                top = limit_digit if tight else 9
                for digit in range(top + 1):
                    new_started = started or digit != 0
                    if new_started:
                        new_balance = balance + (1 if digit % 2 == 0 else -1)
                        new_remainder = (remainder * 10 + digit) % k
                    else:
