def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending in s whose digits
    are all at most limit.
    """
    if start > finish or not s or any(not ch.isdigit() or int(ch) > limit for ch in s):
        return 0

    suffix = int(s)
    suffix_length = len(s)
    scale = 10 ** suffix_length

    def count_prefixes_at_most(bound: int, length: int) -> int:
        """Count valid fixed-length (non-leading-zero) prefixes <= bound."""
        minimum = 10 ** (length - 1)
        if bound < minimum:
            return 0
        top = str(min(bound, 10 ** length - 1))

        @lru_cache(maxsize=None)
        def dp(pos: int, tight: bool) -> int:
            if pos == length:
                return 1
            upper = int(top[pos]) if tight else limit
            first = 1 if pos == 0 else 0
            total = 0
            for digit in range(first, min(upper, limit) + 1):
                total += dp(pos + 1, tight and digit == upper)
            return total

        return dp(0, True)

    answer = 0
    for number_length in range(suffix_length, len(str(finish)) + 1):
        lower_number = max(start, 10 ** (number_length - 1))
        upper_number = min(finish, 10 ** number_length - 1)
        if lower_number > upper_number:
            continue

        if number_length == suffix_length:
            if lower_number <= suffix <= upper_number:
                answer += 1
            continue

        prefix_length = number_length - suffix_length
        lower_prefix = max(
            10 ** (prefix_length - 1),
            (lower_number - suffix + scale - 1) // scale,
        )
        upper_prefix = min(
            10 ** prefix_length - 1,
            (upper_number - suffix) // scale,
        )
        if lower_prefix <= upper_prefix:
            answer += (count_prefixes_at_most(upper_prefix, prefix_length)
                       - count_prefixes_at_most(lower_prefix - 1, prefix_length))

    return answer

