from functools import lru_cache


def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count in-range numbers ending in s whose digits are all at most limit."""
    if start > finish or not s or any(int(ch) > limit for ch in s):
        return 0
    suffix = int(s)
    scale = 10 ** len(s)

    def count_prefixes_at_most(bound: int, length: int) -> int:
        """Count length-digit (non-leading-zero) strings <= bound with digits <= limit."""
        if bound < 10 ** (length - 1):
            return 0
        top = str(min(bound, 10 ** length - 1))

        @lru_cache(None)
        def dp(pos: int, tight: bool) -> int:
            if pos == length:
                return 1
            upper = int(top[pos]) if tight else limit
            total = 0
            for digit in range(1 if pos == 0 else 0, min(upper, limit) + 1):
                total += dp(pos + 1, tight and digit == upper)
            return total
        return dp(0, True)

    answer = 0
    for length in range(len(s), len(str(finish)) + 1):
        min_number = max(start, 10 ** (length - 1))
        max_number = min(finish, 10 ** length - 1)
        if min_number > max_number:
            continue
        if length == len(s):
            if min_number <= suffix <= max_number:
                answer += 1
            continue
        prefix_len = length - len(s)
        lo = max(10 ** (prefix_len - 1), (min_number - suffix + scale - 1) // scale)
        hi = min(10 ** prefix_len - 1, (max_number - suffix) // scale)
        if lo <= hi:
            answer += count_prefixes_at_most(hi, prefix_len) - count_prefixes_at_most(lo - 1, prefix_len)
    return answer

