"""Reference implementations for the six assigned Python utility functions."""
from math import gcd
from typing import List


def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] ending in s with bounded digits."""
    if start > finish or not s or any(int(ch) > limit for ch in s):
        return 0
    suffix_len = len(s)

    def prefix_count(p: int) -> int:
        return 1 if p == 0 else limit * (limit + 1) ** (p - 1)

    def strictly_less(prefix: str) -> int:
        total = 0
        p = len(prefix)
        for i, ch in enumerate(prefix):
            d = ord(ch) - 48
            lo = 1 if i == 0 else 0
            hi = min(limit, d - 1)
            if hi >= lo:
                total += (hi - lo + 1) * (limit + 1) ** (p - i - 1)
            if d < lo or d > limit:
                return total
        return total

    def count_leq(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = str(bound)
        total = sum(prefix_count(length - suffix_len)
                    for length in range(max(1, suffix_len), len(digits)))
        if len(digits) >= suffix_len:
            p = len(digits) - suffix_len
            pref = digits[:p]
            total += strictly_less(pref)
            if s <= digits[p:] and (p == 0 or (pref[0] != "0" and
                    all(ord(ch) - 48 <= limit for ch in pref))):
                total += 1
        return total

    return count_leq(finish) - count_leq(start - 1)


def count_valid_colorings(n: int, m: int) -> int:
    """Count proper colorings of an n-vertex cycle modulo 998244353."""
    mod = 998244353
    return (pow(m - 1, n, mod) +
            (m - 1 if n % 2 == 0 else -(m - 1))) % mod


def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Return twice the black area in [A,C] x [B,D] for the wallpaper pattern."""
    # The coloring is periodic with periods 4 in x and 2 in y. Prefix areas
    # in one period are stored doubled, so all calculations use integers.
    vertical = (0, 3, 6, 7, 8)  # x in [0,r], y in [0,2]
    horizontal = (0, 4)         # x in [0,4], y in [0,s]
    partial = (0, 2, 3, 3, 4)  # x in [0,r], y in [0,1]

    def prefix(x: int, y: int) -> int:
        qx, rx = divmod(x, 4)
        qy, ry = divmod(y, 2)
        return (8 * qx * qy + horizontal[ry] * qx
                + vertical[rx] * qy + (partial[rx] if ry else 0))

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th positive integer divisible by at least one denomination."""
    useful = sorted(set(coins))
    filtered = []
    for c in useful:
        if not any(c % d == 0 for d in filtered):
            filtered.append(c)

    high = min(filtered) * k
    cap = high + 1
    lcms = [1]
    signs = [-1]  # The empty subset has the opposite sign to a singleton.
    for c in filtered:
        old_len = len(lcms)
        for i in range(old_len):
            new_lcm = lcms[i] // gcd(lcms[i], c) * c
            lcms.append(min(new_lcm, cap))
            signs.append(-signs[i])

    def count(x: int) -> int:
        return sum(sign * (x // lcm)
                   for lcm, sign in zip(lcms[1:], signs[1:]) if lcm <= x)

    low = 1
    while low < high:
        mid = (low + high) // 2
        if count(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize |k - OR(subarray)| over all non-empty contiguous subarrays."""
    best = float("inf")
    endings = set()
    for value in nums:
        current = {value}
        current.update(previous | value for previous in endings)
        for combined in current:
            difference = abs(combined - k)
            if difference < best:
                best = difference
                if best == 0:
                    return 0
        endings = current
    return int(best)


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers with equally many even/odd digits, divisible by k."""
    def count_at_most(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = [int(ch) for ch in str(bound)]
        # state: (even-minus-odd balance, remainder, started, tight)
        dp = {(0, 0, False, True): 1}
        for limit_digit in digits:
            nxt = {}
            for (balance, remainder, started, tight), ways in dp.items():
                top = limit_digit if tight else 9
                for digit in range(top + 1):
                    new_started = started or digit != 0
                    if new_started:
                        new_balance = balance + (1 if digit % 2 == 0 else -1)
                        new_remainder = (remainder * 10 + digit) % k
                    else:
                        new_balance = new_remainder = 0
                    state = (new_balance, new_remainder, new_started,
                             tight and digit == top)
                    nxt[state] = nxt.get(state, 0) + ways
            dp = nxt
        return sum(ways for (balance, remainder, started, _), ways in dp.items()
                   if started and balance == 0 and remainder == 0)

    return count_at_most(high) - count_at_most(low - 1)

from functools import lru_cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers in [low, high] divisible by k with equal even/odd digit counts."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))

        @lru_cache(None)
        def dp(pos: int, remainder: int, balance: int, started: bool, tight: bool) -> int:
            if pos == len(digits):
                return int(started and remainder == 0 and balance == 0)
            limit = digits[pos] if tight else 9
            total = 0
            for digit in range(limit + 1):
                next_tight = tight and digit == limit
                if not started and digit == 0:
                    total += dp(pos + 1, remainder, balance, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    total += dp(pos + 1, (remainder * 10 + digit) % k,
                                next_balance, True, next_tight)
            return total

        return dp(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

from typing import List


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize |k - OR(subarray)| over all non-empty contiguous subarrays."""
    best = float("inf")
    previous = []
    for value in nums:
        current = [value]
        for old_or in previous:
            combined = old_or | value
            if combined != current[-1]:
                current.append(combined)
        for subarray_or in current:
            best = min(best, abs(k - subarray_or))
            if best == 0:
                return 0
        previous = current
    return int(best)

def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Return twice the black area in the specified AtCoder wallpaper rectangle."""
    # Entries are twice the black area in unit cells; this pattern repeats every 4.
    rows = (
        (2, 1, 2, 1),
        (1, 2, 1, 2),
        (0, 1, 0, 1),
        (1, 0, 1, 0),
    )

    def periodic_prefix(values, n):
        q, r = divmod(n, len(values))
        return q * sum(values) + sum(values[:r])

    column_totals = tuple(sum(rows[i][j] for i in range(4)) for j in range(4))

    def prefix(x, y):
        q, r = divmod(x, 4)
        result = q * periodic_prefix(column_totals, y)
        for i in range(r):
            result += periodic_prefix(rows[i], y)
        return result

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
